from pathlib import Path
from datetime import datetime
import shutil
import sys

ROOT = Path.cwd()
TARGET = ROOT / "components/world/calendar-event-notification-badge.tsx"

def fail(message: str) -> None:
    print(f"\nERROR: {message}\n")
    sys.exit(1)

if not TARGET.exists():
    fail("Could not find components/world/calendar-event-notification-badge.tsx. Run this from the Sepulchria repo root.")

stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
backup = ROOT / f".patch-backup-recurring-event-notifications-{stamp}" / TARGET.relative_to(ROOT)
backup.parent.mkdir(parents=True, exist_ok=True)
shutil.copy2(TARGET, backup)

replacement = '"use client";\n\nimport {\n  useCallback,\n  useEffect,\n  useMemo,\n  useState,\n} from "react";\n\nimport { createClient } from "@/lib/supabase/client";\nimport {\n  fromIsoDateKey,\n} from "@/lib/world/calendar";\n\ntype CalendarEventNotificationBadgeProps = {\n  characterId: string | null;\n  gameDate: Date;\n  calendarOpen: boolean;\n};\n\ntype CalendarEventRow = {\n  id: string;\n  event_date: string;\n  recurrence_type:\n    | "once"\n    | "daily"\n    | "weekly"\n    | "monthly"\n    | "yearly";\n  start_time: string | null;\n  end_time: string | null;\n  notify_24h: boolean;\n  notify_1h: boolean;\n};\n\ntype ActiveReminder = {\n  eventId: string;\n  windowStart: number;\n};\n\nconst DAY_MS = 24 * 60 * 60 * 1000;\nconst HOUR_MS = 60 * 60 * 1000;\n\nfunction utcDay(date: Date) {\n  return new Date(\n    Date.UTC(\n      date.getUTCFullYear(),\n      date.getUTCMonth(),\n      date.getUTCDate(),\n      12,\n    ),\n  );\n}\n\nfunction addUtcDays(date: Date, amount: number) {\n  return new Date(\n    Date.UTC(\n      date.getUTCFullYear(),\n      date.getUTCMonth(),\n      date.getUTCDate() + amount,\n      12,\n    ),\n  );\n}\n\nfunction daysBetween(first: Date, second: Date) {\n  return Math.floor(\n    (\n      Date.UTC(\n        second.getUTCFullYear(),\n        second.getUTCMonth(),\n        second.getUTCDate(),\n      ) -\n      Date.UTC(\n        first.getUTCFullYear(),\n        first.getUTCMonth(),\n        first.getUTCDate(),\n      )\n    ) /\n      DAY_MS,\n  );\n}\n\nfunction daysInMonth(year: number, monthIndex: number) {\n  return new Date(\n    Date.UTC(\n      year,\n      monthIndex + 1,\n      0,\n      12,\n    ),\n  ).getUTCDate();\n}\n\nfunction occursOnDate(\n  event: CalendarEventRow,\n  date: Date,\n) {\n  const first =\n    fromIsoDateKey(\n      event.event_date,\n    );\n\n  if (date < first) {\n    return false;\n  }\n\n  if (event.recurrence_type === "once") {\n    return (\n      date.getUTCFullYear() === first.getUTCFullYear() &&\n      date.getUTCMonth() === first.getUTCMonth() &&\n      date.getUTCDate() === first.getUTCDate()\n    );\n  }\n\n  if (event.recurrence_type === "daily") {\n    return true;\n  }\n\n  if (event.recurrence_type === "weekly") {\n    return daysBetween(first, date) % 7 === 0;\n  }\n\n  if (event.recurrence_type === "monthly") {\n    const expectedDay =\n      Math.min(\n        first.getUTCDate(),\n        daysInMonth(\n          date.getUTCFullYear(),\n          date.getUTCMonth(),\n        ),\n      );\n\n    return date.getUTCDate() === expectedDay;\n  }\n\n  if (event.recurrence_type === "yearly") {\n    if (date.getUTCMonth() !== first.getUTCMonth()) {\n      return false;\n    }\n\n    const expectedDay =\n      Math.min(\n        first.getUTCDate(),\n        daysInMonth(\n          date.getUTCFullYear(),\n          first.getUTCMonth(),\n        ),\n      );\n\n    return date.getUTCDate() === expectedDay;\n  }\n\n  return false;\n}\n\nfunction parseTime(value: string | null) {\n  if (!value) {\n    return null;\n  }\n\n  const match =\n    value.match(\n      /^([01]\\d|2[0-3]):([0-5]\\d)/,\n    );\n\n  if (!match) {\n    return null;\n  }\n\n  return {\n    hour: Number(match[1]),\n    minute: Number(match[2]),\n  };\n}\n\nfunction withTime(\n  date: Date,\n  time: {\n    hour: number;\n    minute: number;\n  },\n) {\n  return new Date(\n    Date.UTC(\n      date.getUTCFullYear(),\n      date.getUTCMonth(),\n      date.getUTCDate(),\n      time.hour,\n      time.minute,\n      0,\n      0,\n    ),\n  );\n}\n\nfunction getActiveReminder(\n  event: CalendarEventRow,\n  gameDate: Date,\n): ActiveReminder | null {\n  const startClock =\n    parseTime(\n      event.start_time,\n    );\n\n  if (!startClock) {\n    return null;\n  }\n\n  if (\n    !event.notify_24h &&\n    !event.notify_1h\n  ) {\n    return null;\n  }\n\n  const today =\n    utcDay(\n      gameDate,\n    );\n\n  const candidates = [\n    today,\n    addUtcDays(today, 1),\n  ];\n\n  const now =\n    gameDate.getTime();\n\n  for (const date of candidates) {\n    if (!occursOnDate(event, date)) {\n      continue;\n    }\n\n    const occurrenceStart =\n      withTime(\n        date,\n        startClock,\n      ).getTime();\n\n    const endClock =\n      parseTime(\n        event.end_time,\n      );\n\n    const occurrenceEnd =\n      endClock\n        ? withTime(\n            date,\n            endClock,\n          ).getTime()\n        : occurrenceStart + HOUR_MS;\n\n    const reminderLead =\n      event.notify_24h\n        ? DAY_MS\n        : HOUR_MS;\n\n    const windowStart =\n      occurrenceStart -\n      reminderLead;\n\n    if (\n      now >= windowStart &&\n      now < occurrenceEnd\n    ) {\n      return {\n        eventId: event.id,\n        windowStart,\n      };\n    }\n  }\n\n  return null;\n}\n\nexport function CalendarEventNotificationBadge({\n  characterId,\n  gameDate,\n  calendarOpen,\n}: CalendarEventNotificationBadgeProps) {\n  const supabase =\n    useMemo(\n      () => createClient(),\n      [],\n    );\n\n  const [count, setCount] =\n    useState(0);\n\n  const [\n    activeReminders,\n    setActiveReminders,\n  ] = useState<ActiveReminder[]>([]);\n\n  const loadUnread =\n    useCallback(async () => {\n      if (!characterId) {\n        setCount(0);\n        setActiveReminders([]);\n        return;\n      }\n\n      const {\n        data: events,\n        error: eventsError,\n      } = await supabase\n        .from("calendar_events")\n        .select(\n          "id,event_date,recurrence_type,start_time,end_time,notify_24h,notify_1h",\n        )\n        .eq("is_active", true)\n        .or(\n          "notify_24h.eq.true,notify_1h.eq.true",\n        );\n\n      if (eventsError) {\n        console.error(\n          "Unable to load calendar Event reminders:",\n          eventsError.message,\n        );\n        return;\n      }\n\n      const reminders =\n        (events ?? [])\n          .map(\n            (event) =>\n              getActiveReminder(\n                {\n                  id: String(event.id),\n                  event_date:\n                    String(event.event_date),\n                  recurrence_type:\n                    (\n                      event.recurrence_type ??\n                      "once"\n                    ) as CalendarEventRow["recurrence_type"],\n                  start_time:\n                    event.start_time ??\n                    null,\n                  end_time:\n                    event.end_time ??\n                    null,\n                  notify_24h:\n                    event.notify_24h ===\n                    true,\n                  notify_1h:\n                    event.notify_1h ===\n                    true,\n                },\n                gameDate,\n              ),\n          )\n          .filter(\n            (\n              reminder,\n            ): reminder is ActiveReminder =>\n              Boolean(reminder),\n          );\n\n      setActiveReminders(reminders);\n\n      if (reminders.length === 0) {\n        setCount(0);\n        return;\n      }\n\n      const eventIds =\n        reminders.map(\n          (reminder) =>\n            reminder.eventId,\n        );\n\n      const {\n        data: reads,\n        error: readsError,\n      } = await supabase\n        .from(\n          "calendar_event_reads",\n        )\n        .select(\n          "event_id,checked_at",\n        )\n        .eq(\n          "character_id",\n          characterId,\n        )\n        .in(\n          "event_id",\n          eventIds,\n        );\n\n      if (readsError) {\n        console.error(\n          "Unable to load calendar Event reads:",\n          readsError.message,\n        );\n        return;\n      }\n\n      const checkedByEvent =\n        new Map(\n          (reads ?? []).map(\n            (read) => [\n              String(read.event_id),\n              Date.parse(\n                String(\n                  read.checked_at ??\n                  "",\n                ),\n              ),\n            ],\n          ),\n        );\n\n      const unread =\n        reminders.filter(\n          (reminder) => {\n            const checkedAt =\n              checkedByEvent.get(\n                reminder.eventId,\n              );\n\n            return (\n              checkedAt === undefined ||\n              Number.isNaN(checkedAt) ||\n              checkedAt <\n                reminder.windowStart\n            );\n          },\n        );\n\n      setCount(unread.length);\n    }, [\n      characterId,\n      gameDate,\n      supabase,\n    ]);\n\n  const markActiveRemindersRead =\n    useCallback(async () => {\n      if (\n        !characterId ||\n        activeReminders.length === 0\n      ) {\n        return;\n      }\n\n      const now =\n        new Date().toISOString();\n\n      const {\n        error,\n      } = await supabase\n        .from(\n          "calendar_event_reads",\n        )\n        .upsert(\n          activeReminders.map(\n            (reminder) => ({\n              character_id:\n                characterId,\n              event_id:\n                reminder.eventId,\n              checked_at:\n                now,\n            }),\n          ),\n          {\n            onConflict:\n              "character_id,event_id",\n          },\n        );\n\n      if (error) {\n        console.error(\n          "Unable to save calendar Event reads:",\n          error.message,\n        );\n        return;\n      }\n\n      setCount(0);\n    }, [\n      activeReminders,\n      characterId,\n      supabase,\n    ]);\n\n  useEffect(() => {\n    void loadUnread();\n\n    if (!characterId) {\n      return;\n    }\n\n    const channel =\n      supabase\n        .channel(\n          `calendar-notifications-${characterId}`,\n        )\n        .on(\n          "postgres_changes",\n          {\n            event: "*",\n            schema: "public",\n            table: "calendar_events",\n          },\n          () => {\n            void loadUnread();\n          },\n        )\n        .subscribe();\n\n    const timer =\n      window.setInterval(\n        () => {\n          void loadUnread();\n        },\n        30_000,\n      );\n\n    return () => {\n      window.clearInterval(timer);\n      void supabase.removeChannel(channel);\n    };\n  }, [\n    characterId,\n    loadUnread,\n    supabase,\n  ]);\n\n  useEffect(() => {\n    if (!calendarOpen) {\n      return;\n    }\n\n    void markActiveRemindersRead();\n  }, [\n    calendarOpen,\n    markActiveRemindersRead,\n  ]);\n\n  if (count <= 0) {\n    return null;\n  }\n\n  return (\n    <span\n      aria-label={`${count} unread calendar Event reminder${\n        count === 1\n          ? ""\n          : "s"\n      }`}\n      className="absolute -right-1.5 -top-1.5 z-20 flex h-4 min-w-4 items-center justify-center rounded-full border border-[rgb(var(--sep-colour-d6ad6b))] bg-[rgb(var(--sep-colour-8f321f))] px-1 text-[8px] font-bold leading-none text-[rgb(var(--sep-colour-fff1d5))] shadow-[0_2px_8px_rgba(var(--sep-rgb-0-0-0),0.65)] components_world_calendar_event_notification_badge_span_text"\n    >\n      {count > 99\n        ? "99+"\n        : count}\n    </span>\n  );\n}\n'
TARGET.write_text(replacement, encoding="utf-8")

print("Patch applied successfully.")
print("Changed: components/world/calendar-event-notification-badge.tsx")
print(f"Backup: {backup.parent}")
print()
print("Fixes:")
print("  - recurring Event reminders are occurrence-aware")
print("  - an old read from a previous recurrence no longer suppresses today's reminder")
print("  - notify_24h / notify_1h are actually respected")
print("  - reminders use Aureth game time")
print("  - opening the calendar marks only the currently-active occurrence reminders as read")
print("  - the badge refreshes every 30 seconds and on Event changes")
print()
print("Nothing was committed or pushed.")
